@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class BusinessAccount extends Account {
  + CompanyName : string
  + MonthlyFee : double
}

class PersonalAccount extends Account {
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage extends Page {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "0..1" Account
Account "1" *-- "*" Page
PersonalAccount "0..1" ..> "0..*" Page : granted privileges
BusinessAccount "1" -- "*" AdvertisementPage

@enduml

